mapper.insert:
INSERT INTO body_compositions (
    body_composition_id, member_id, measured_date,
    weight, skeletal_muscle, body_fat_percentage
) VALUES (
    SEQ_BODY_COMPOSITIONS.NEXTVAL, #{memberId}, #{measuredDate,jdbcType=DATE},
    #{weight,jdbcType=NUMERIC}, #{skeletalMuscle,jdbcType=NUMERIC},
    #{bodyFatPercentage,jdbcType=NUMERIC}
)

mapper.select:
SELECT COUNT(*)
FROM body_compositions
WHERE member_id = #{memberId}
  AND TRUNC(measured_date) = #{measuredDate,jdbcType=DATE}

mapper.delete:
DELETE FROM body_compositions
WHERE body_composition_id = #{bodyCompositionId}
  AND member_id = #{memberId}
